class Solution {
public:
    int countPartitions(vector<int>& nums, int k) {
        const long long MOD = 1000000007;
        long long total = 0;
        for (int x : nums) total += x;
        if (total < 2LL * k) return 0;

        vector<long long> dp(k, 0);
        dp[0] = 1;
        for (int x : nums) {
            if (x >= k) continue;
            for (int s = k - 1; s >= x; s--) {
                dp[s] = (dp[s] + dp[s - x]) % MOD;
            }
        }

        long long bad = 0;
        for (int s = 0; s < k; s++) bad = (bad + dp[s]) % MOD;
        bad = bad * 2 % MOD;

        long long p2 = 1;
        for (int i = 0; i < (int)nums.size(); i++) p2 = p2 * 2 % MOD;

        long long ans = (p2 - bad + MOD) % MOD;
        return (int)ans;
    }
};
